def longest_common_prefix(words: list[str]) -> str:
    if not words:
        return ""
    first = words[0]
    for i, letter in enumerate(first):
        for word in words:
            if i >= len(word) or word[i] != letter:
                return first[:i]
    return first


n = int(input())
words = input().split()
prefix = longest_common_prefix(words[:n])
print(prefix if prefix else "none")

