package main

import "fmt"

func longestCommonPrefix(words []string) string {
	if len(words) == 0 {
		return ""
	}
	first := words[0]
	// Indexing a string gives a byte. The words are plain ASCII letters,
	// so every byte is one whole letter.
	for i := 0; i < len(first); i++ {
		for _, word := range words {
			if i >= len(word) || word[i] != first[i] {
				return first[:i]
			}
		}
	}
	return first
}

func main() {
	var n int
	fmt.Scan(&n)
	words := make([]string, n)
	for i := range words {
		fmt.Scan(&words[i])
	}
	prefix := longestCommonPrefix(words)
	if prefix == "" {
		prefix = "none"
	}
	fmt.Println(prefix)
}

