import { readFileSync } from "node:fs";

const input = readFileSync(0, "utf8");

function longestCommonPrefix(words: string[]): string {
  const first = words[0];
  if (first === undefined) {
    return "";
  }
  for (let i = 0; i < first.length; i++) {
    const letter = first.charAt(i);
    for (const word of words) {
      // charAt past the end of a word gives "", which never matches a letter
      if (word.charAt(i) !== letter) {
        return first.substring(0, i);
      }
    }
  }
  return first;
}

const [n = "0", ...words] = input.trim().split(/\s+/);
const prefix = longestCommonPrefix(words.slice(0, Number(n)));
console.log(prefix === "" ? "none" : prefix);
